// ## src/middleware/logger.js
export function logger(req, res, next) {
  const start = process.hrtime.bigint()
  res.on('finish', () => {
    const ms = Number(process.hrtime.bigint() - start) / 1e6
    console.log(`${req.method} ${req.originalUrl} ${res.statusCode} ${ms.toFixed(1)}ms`)
  })
  next()
}

// ## src/middleware/auth.js
export function apiKeyAuth(req, res, next) {
  const key = req.get('x-api-key')
  if (!key || key !== process.env.API_KEY) {
    return res.status(401).json({ error: 'Invalid or missing API key' })
  }
  req.user = { id: 1, role: 'admin' }
  next()
}

export const requireRole = (role) => (req, res, next) => {
  if (req.user?.role !== role) return res.status(403).json({ error: 'Forbidden' })
  next()
}

// ## src/app.js
import express from 'express'
import { logger } from './middleware/logger.js'
import { apiKeyAuth, requireRole } from './middleware/auth.js'

const app = express()
app.use(logger)
app.get('/public', (req, res) => res.send('open to all'))
app.get('/secret', apiKeyAuth, requireRole('admin'), (req, res) => res.json({ secret: 42 }))
app.listen(3000)

function miniExpress() {
  const stack = []
  const app = {
    use(fn) { stack.push(fn); return app },
    handle(req, res) {
      let i = 0
      function next(err) {
        const fn = stack[i++]
        if (!fn) {
          return err ? res.send(500, 'Unhandled: ' + err.message)
                     : res.send(404, 'Not found')
        }
        const isErrorHandler = fn.length === 4
        try {
          if (err && isErrorHandler) fn(err, req, res, next)
          else if (!err && !isErrorHandler) fn(req, res, next)
          else next(err)               // skip: wrong kind of function
        } catch (e) { next(e) }        // thrown error -> next(err)
      }
      next()
    }
  }
  return app
}

const app = miniExpress()
app.use((req, res, next) => { console.log('logger:', req.url); next() })
app.use((req, res, next) => {
  req.user = req.url.includes('admin') ? { role: 'admin' } : null
  next()
})
app.use((req, res, next) => {
  if (req.url === '/crash') throw new Error('boom')
  next()
})
app.use((req, res, next) => {
  if (req.url === '/') return res.send(200, 'home')
  if (req.url === '/admin' && req.user) return res.send(200, 'admin panel')
  next()
})
app.use((err, req, res, next) => {
  console.log('error handler got:', err.message)
  res.send(500, 'Something went wrong')
})

for (const url of ['/', '/admin', '/missing', '/crash']) {
  app.handle({ url }, { send: (code, body) => console.log(`${url} -> ${code} ${body}\n`) })
}
